initial_condition:
with {
    the SUT in the "initial state"
}

test_cases.then:
then {
    the SUT sends a valid Response for the operations:
        Delete Subscription with Response Status Code set to 400     and
        Delete Subscription with Response Body containing the type 'https://uri.etsi.org/ngsi-ld/errors/BadRequestData'     and
        Delete Subscription with Response body containing 'title' element
}

test_cases.when:
when {
    the SUT receives a Request from the client containing:
        URL set to '/ngsi-ld/v1/subscriptions/{subscription_id}'
        method set to 'DELETE'
        Delete Subscription with id set to '${EMPTY}'
}

test_cases.then:
then {
    the SUT sends a valid Response for the operations:
        Delete Subscription with Response Status Code set to 400     and
        Delete Subscription with Response Body containing the type 'https://uri.etsi.org/ngsi-ld/errors/BadRequestData'     and
        Delete Subscription with Response body containing 'title' element
}

test_cases.when:
when {
    the SUT receives a Request from the client containing:
        URL set to '/ngsi-ld/v1/subscriptions/{subscription_id}'
        method set to 'DELETE'
        Delete Subscription with id set to 'InvalidUri'
}
